<?php
declare(strict_types=1);
function report_query():array{
 $s=site();$today=local_time(now(),'Y-m-d');$from=is_string($_GET['from']??null)?$_GET['from']:$today;$to=is_string($_GET['to']??null)?$_GET['to']:$today;
 try{$start=parse_local($from.'T00:00',$s['timezone']);$finish=parse_local($to.'T00:00',$s['timezone'])->setTimezone(new DateTimeZone($s['timezone']))->modify('+1 day')->setTimezone(new DateTimeZone('UTC'));}catch(Throwable $e){fail(400,'Invalid report dates.');}
 if($finish<=$start||$finish->getTimestamp()-$start->getTimestamp()>367*86400)fail(400,'Choose a report period of up to one year.');
 $sql=' FROM ks_records r WHERE site_id=? AND observed_at>=? AND observed_at<?';$params=[$s['id'],$start->format('Y-m-d H:i:s'),$finish->format('Y-m-d H:i:s')];
 $kind=is_string($_GET['kind']??null)?$_GET['kind']:'';if($kind!==''&&($kind==='task'||isset(KINDS[$kind]))){$sql.=' AND kind=?';$params[]=$kind;}
 $q=trim(is_string($_GET['q']??null)?$_GET['q']:'');if($q!==''){$sql.=' AND (subject LIKE ? OR user_name LIKE ?)';$params[]='%'.mb_substr($q,0,150).'%';$params[]='%'.mb_substr($q,0,150).'%';}
 return [$sql,$params,$from,$to,$kind,$q];
}
function export_report():void{
 need_manager();[$sql,$params,$from,$to]=report_query();$mode=$_GET['export'];$s=site();db()->beginTransaction();$count=(int)one('SELECT COUNT(*) n'.$sql,$params)['n'];
 if($mode==='csv'){
  header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="kitchen-records-'.$from.'-to-'.$to.'.csv"');$out=fopen('php://output','wb');fwrite($out,"\xEF\xBB\xBF");
  $safe=function($v){$v=(string)($v??'');return preg_match('/^[\s]*[=+@-]/u',$v)?"'".$v:$v;};
  $write=function($values)use($out,$safe){fputcsv($out,array_map($safe,$values),',','"','');};
  $write(['Row type','Record ID','Kitchen snapshot','Check type','Item snapshot','Measured local','Time zone','Measured UTC','Saved UTC','Staff snapshot','Temperature C','Hold seconds','Original result','Current result','Resolved','Limits JSON','Payload JSON','Notes','Late reason','Scheduled UTC','Event type','Event author','Event saved UTC','Event notes','Event data JSON']);
  $offset=0;while(true){$batch=rows('SELECT r.*'.$sql.' ORDER BY observed_at,id LIMIT 500 OFFSET '.$offset,$params);if(!$batch)break;foreach($batch as $r){$st=state($r);$write(['reading',$r['id'],$r['site_name'],KINDS[$r['kind']]??'Routine check',$r['subject'],local_time($r['observed_at'],'Y-m-d H:i',$r['timezone']),$r['timezone'],$r['observed_at'],$r['recorded_at'],$r['user_name'],$r['temperature'],$r['hold_seconds'],$r['status'],$st['status'],$st['closed']?'yes':'no',$r['limits_json'],$r['payload_json'],$r['notes'],$r['late_reason'],$r['scheduled_for'],'','','','','']);foreach($st['events'] as $ev)$write(['event',$r['id'],$r['site_name'],'',$r['subject'],'','','','','','','','','','','','','','','',$ev['type'],$ev['user_name'],$ev['created_at'],$ev['body'],$ev['data_json']]);}$offset+=500;}
  $write(['REPORT METADATA','',$s['name'],'Date range '.$from.' to '.$to.'; measured-time filter; exported '.now().' UTC; reviewed by '.user()['name']]);
  foreach(rows('SELECT * FROM ks_reviews WHERE site_id=? AND review_date BETWEEN ? AND ? ORDER BY id',[$s['id'],$from,$to]) as $rv)$write(['daily review',$rv['id'],$s['name'],$rv['review_date'],'','','','','',$rv['user_name'],'','','','','','','',$rv['notes'],'','','review',$rv['user_name'],$rv['created_at'],'',$rv['snapshot_json']]);
  // Timetable rows include missed slots, even when no temperature reading exists.
  $day=new DateTimeImmutable($from,new DateTimeZone($s['timezone']));$last=new DateTimeImmutable($to,new DateTimeZone($s['timezone']));for(;$day<=$last;$day=$day->modify('+1 day'))foreach(scheduled_items($s,$day->format('Y-m-d')) as $slot)$write(['schedule',$slot['record']['id']??'',$s['name'],KINDS[$slot['kind']]??'Routine check',$slot['name'],'',$s['timezone'],'','','','','','',$slot['state'],'','','','','',$slot['utc']]);
  fclose($out);db()->commit();audit('report.csv','site:'.$s['id'],['from'=>$from,'to'=>$to,'records'=>$count]);return;
 }
 if($mode!=='print')fail(400,'Unknown report format.');if($count>1000)fail(400,'Print reports support 1,000 readings at a time. Choose a shorter date range or use CSV.');
 head('Kitchen safety report','',true);echo '<div class="print-toolbar"><button class="btn primary" data-print>Print / save as PDF</button><a class="btn" href="'.e(url('p=history&from='.$from.'&to='.$to)).'">Back to reports</a></div><header class="report-title"><p class="eyebrow">MUSTRHQ · KITCHEN SAFETY</p><h1>'.e($s['name']).'</h1><p>'.e($from).' to '.e($to).' · '.e($s['timezone']).'</p><p class="help">Generated '.e(local_time(now())).' by '.e(user()['name']).'. Filtered by measured date. Original readings and later events are preserved.</p></header>';
 foreach(rows('SELECT r.*'.$sql.' ORDER BY observed_at,id',$params) as $r){$st=state($r);echo '<section class="report-record"><h2>#'.(int)$r['id'].' · '.e($r['subject']).' '.badge($st['status']).'</h2><p>'.e(KINDS[$r['kind']]??'Routine check').' · Measured '.e(local_time($r['observed_at'],zone:$r['timezone'])).' · '.e($r['user_name']).'</p><p><strong>'.($r['temperature']!==null?e((float)$r['temperature']).'°C':'Routine check').'</strong>'.($r['hold_seconds']!==null?' · '.$r['hold_seconds'].' sec':'').' · Original result: '.e($r['status']).' · '.e(limits_label(arr($r['limits_json']))).'</p><p class="help">Saved '.e($r['recorded_at']).' UTC · Kitchen: '.e($r['site_name']).' · Resolved: '.($st['closed']?'yes':'no').'</p><p>'.nl2br(e($r['notes'])).'</p>';if($r['late_reason'])echo '<p>Late entry: '.e($r['late_reason']).'</p>';echo '<p class="help">Details: '.e($r['payload_json']).'</p>';foreach($st['events'] as $ev)echo '<div class="report-event"><strong>'.e($ev['type']).'</strong> · '.e($ev['user_name']).' · '.e(local_time($ev['created_at'],zone:$r['timezone'])).'<p>'.nl2br(e($ev['body'])).'</p><p class="help">'.e($ev['data_json']).'</p></div>';echo '</section>';}
 echo '<h2>Daily schedule evidence</h2><p class="help">Includes all scheduled checks for this period, regardless of any reading filters above. “Overdue” includes slots missed on previous days. Schedule revisions retain the timetable in force at each slot.</p><table><thead><tr><th>Day / time</th><th>Item</th><th>Slot result</th></tr></thead><tbody>';
 $day=new DateTimeImmutable($from,new DateTimeZone($s['timezone']));$last=new DateTimeImmutable($to,new DateTimeZone($s['timezone']));for(;$day<=$last;$day=$day->modify('+1 day'))foreach(scheduled_items($s,$day->format('Y-m-d')) as $slot)echo '<tr><td>'.e($day->format('d M Y').' '.$slot['slot']).'</td><td>'.e($slot['name']).'</td><td>'.e($slot['state']).($slot['record']?' · #'.$slot['record']['id']:'').'</td></tr>';echo '</tbody></table><h2>Manager reviews</h2>';
 foreach(rows('SELECT * FROM ks_reviews WHERE site_id=? AND review_date BETWEEN ? AND ? ORDER BY id',[$s['id'],$from,$to]) as $rv)echo '<section class="report-record"><h3>'.e($rv['review_date']).' · '.e($rv['user_name']).'</h3><p>'.nl2br(e($rv['notes'])).'</p><p class="help">Review snapshot: '.e($rv['snapshot_json']).' · Saved '.e($rv['created_at']).' UTC</p></section>';
 echo '<p class="help">Monitoring evidence supports your HACCP procedures. A recorded temperature alone does not certify that food is safe.</p>';db()->commit();audit('report.print','site:'.$s['id'],['from'=>$from,'to'=>$to,'records'=>$count]);foot(true);
}
